import React, { useState, useEffect } from "react";
import "./ViewTasks.css"; 
import Navbar from "../components/navbar"; 
import Footer from "../components/footer"; 
import StudentSidebar from "../components/StudentSidebar"; 
import Axios from "axios"; 

const ViewTasks = () => {
  // State to manage the list of milestones
  const [milestones, setMilestones] = useState([]);

  // State to store new milestone input
  const [newMilestone, setNewMilestone] = useState("");

  // State for new task input fields
  const [newTask, setNewTask] = useState({
    title: "",
    creator: "",
    status: "Pending",
    deadline: "",
  });

  // Get the current student from localStorage
  const user = JSON.parse(localStorage.getItem('users'));

  // Fetch milestones and tasks from backend
  useEffect(() => {
    const fetchMilestones = async () => {
      try {
        const response = await Axios.get("http://localhost:5000/api/milestone");
        setMilestones(response.data);
      } catch (error) {
        console.error("Error fetching milestones:", error);
      }
    };

    fetchMilestones();
  }, []);

  // Function to add a new milestone
  const handleAddMilestone = async () => {
    if (!newMilestone.trim()) {
      alert("Please enter a milestone name.");
      return;
    }

    const milestoneData = {
      projectID: "project001", // Example project ID, you can dynamically set this
      title: newMilestone,
      dueDate: new Date(), // Set an example due date
      status: "Pending",
    };

    try {
      const response = await Axios.post("http://localhost:5000/api/milestone", milestoneData);
      setMilestones([...milestones, response.data]); // Update state with new milestone
      setNewMilestone(""); // Clear input field
    } catch (error) {
      console.error("Error adding milestone:", error);
    }
  };

  // Function to add a new task under a specific milestone
  const handleAddTask = async (milestoneId) => {
    if (!newTask.title.trim() || !newTask.creator.trim()) {
      alert("Please fill in all task fields.");
      return;
    }

    const taskData = {
      milestoneId,
      title: newTask.title,
      status: newTask.status,
      uploadedBy: user ? user.studentName : "", // Ensure this is correct
    };

    try {
      const response = await Axios.post("http://localhost:5000/api/task", taskData);
      setMilestones((prevMilestones) =>
        prevMilestones.map((milestone) =>
          milestone._id === milestoneId
            ? { ...milestone, tasks: [...milestone.tasks, response.data] }
            : milestone
        )
      );

      // Clear task input fields after adding
      setNewTask({ title: "", creator: "", status: "Pending", deadline: "" });
    } catch (error) {
      console.error("Error adding task:", error.response ? error.response.data : error.message);
    }
  };

  // Function to update task status (e.g., mark as completed)
  const handleUpdateTaskStatus = async (milestoneId, taskId, newStatus) => {
    const updatedTask = {
      status: newStatus,
      completedBy: user ? user.studentName : "",
    };

    try {
      const response = await Axios.patch(`http://localhost:5000/api/task/${taskId}`, updatedTask);
      setMilestones((prevMilestones) =>
        prevMilestones.map((milestone) =>
          milestone._id === milestoneId
            ? {
                ...milestone,
                tasks: milestone.tasks.map((task) =>
                  task._id === taskId ? response.data : task
                ),
              }
            : milestone
        )
      );
    } catch (error) {
      console.error("Error updating task status:", error);
    }
  };

  return (
    <div className="tasks-container">
      <Navbar />
      <div className="content-wrapper">
        <StudentSidebar />
        <div className="main-content">
          <h1 className="tasks-title">Manage Milestones and Tasks</h1>

          {/* Input Field for Adding a Milestone */}
          <div className="milestone-section">
            <input 
              type="text" 
              value={newMilestone} 
              onChange={(e) => setNewMilestone(e.target.value)} 
              placeholder="Add a new milestone" 
            />
            <button onClick={handleAddMilestone}>Add Milestone</button>
          </div>

          {/* List of Milestones with Tasks */}
          <div className="milestone-list">
            {milestones.map((milestone) => (
              <div key={milestone._id} className="milestone-item">
                <h2>{milestone.title}</h2>
                <p>Created on: {milestone.createdAt}</p>

                {/* Input Fields for Adding a Task to the Milestone */}
                <div className="task-section">
                  <input 
                    type="text" 
                    value={newTask.title} 
                    onChange={(e) => setNewTask({ ...newTask, title: e.target.value })} 
                    placeholder="Task title" 
                  />
                  <input 
                    type="text" 
                    value={newTask.creator} 
                    onChange={(e) => setNewTask({ ...newTask, creator: e.target.value })} 
                    placeholder="Created by" 
                  />
                  <button className="task-button" onClick={() => handleAddTask(milestone._id)}>Add Task</button>

                  {/* Table of Tasks Under the Milestone */}
                  <div className="tasks-table">
                    <table>
                      <thead>
                        <tr>
                          <th>Task</th>
                          <th>Creator</th>
                          <th>Status</th>
                          <th>Completed By</th>
                          <th>Created At</th>
                          <th>Actions</th>
                        </tr>
                      </thead>
                      <tbody>
                        {milestone.tasks && milestone.tasks.length > 0 ? (
                          milestone.tasks.map((task) => (
                            <tr key={task._id}>
                              <td>{task.title}</td>
                              <td>{task.uploadedBy}</td>
                              <td>{task.status}</td>
                              <td>{task.completedBy || "N/A"}</td>
                              <td>{task.createdAt}</td>
                              <td>
                                <button 
                                  className="mark-completed-button" 
                                  onClick={() => handleUpdateTaskStatus(milestone._id, task._id, "Completed")}
                                >
                                  Mark as Completed
                                </button>
                              </td>
                            </tr>
                          ))
                        ) : (
                          <tr>
                            <td colSpan="6">No tasks available</td>
                          </tr>
                        )}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default ViewTasks;
